 "content": "def transform(grid):
    # Fill the one-cell-expanded bounding box around the 1-shape: exterior 2,
    # enclosed region 3, preserving the central cell of each enclosed region.
    from collections import deque
    h, w = len(grid), len(grid[0])
    ones = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not ones:
        return [row[:] for row in grid]
