            if grid[r][c] == 0 and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(x,y+1):
        for r in (a,b):
            if grid[r][c] == 0 and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if a<=nr<=b and x<=nc<=y and grid[nr][nc]==0 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(a,b+1):
        for c in range(x,y+1):
            if grid[r][c] == 0:
                out[r][c] = 2 if (r,c) in seen else 3
    # Keep a one-cell hole at the center of each enclosed rectangular cavity.
    for r in range(a+1,b):
        for c in range(x+1,y):
            if grid[r][c] == 0 and out[r][c] == 3:
                # central pixel of the bounding box
                if r == (a+b)//2 and c == (x+y)//2:
                    out[r][c] = 0
    return out
