from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected zero regions and record whether each reaches the edge.
    zero_id = [[-1] * w for _ in range(h)]
    zero_edge = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or zero_id[r][c] != -1:
                continue
            k = len(zero_edge)
            q = deque([(r, c)])
            zero_id[r][c] = k
            edge = False
            while q:
                y, x = q.popleft()
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    edge = True
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and zero_id[yy][xx] == -1:
                        zero_id[yy][xx] = k
                        q.append((yy, xx))
            zero_edge.append(edge)

    # Find each 4-connected 1-object. Only objects bordering an enclosed
    # background region are treated as closed outlines.
    one_seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or one_seen[r][c]:
                continue
            q = deque([(r, c)])
            one_seen[r][c] = True
            component = []
            adjacent_zero_ids = set()
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if not (0 <= yy < h and 0 <= xx < w):
                        continue
                    if grid[yy][xx] == 1 and not one_seen[yy][xx]:
                        one_seen[yy][xx] = True
                        q.append((yy, xx))
                    elif grid[yy][xx] == 0:
                        adjacent_zero_ids.add(zero_id[yy][xx])
            enclosed_ids = {k for k in adjacent_zero_ids if not zero_edge[k]}
            if not enclosed_ids:
                continue
            # Recolor the one-cell neighborhoods: interior-adjacent zeros 3,
            # exterior-adjacent zeros 2. Deeper cavity cells stay 0.
            for y, x in component:
                # The external outline is an 8-neighbor halo, while cavity
